BEGIN;
UPDATE consumable_items SET Effect_Formula='Prevent teleport, blink, swap, and all self-relocating skills and items for 1500 CT; Portal Treads walk normally.' WHERE Item_ID='CON-019';
UPDATE consumable_items SET Effect_Formula='Enemy actions that spend AP in zone add 50 RT for 1200 CT.' WHERE Item_ID='CON-020';
UPDATE consumable_items SET Effect_Formula='Clear Burning and Oily in a 5x5 area and fireproof it for 1200 CT: tiles cannot catch fire, and everyone inside cannot gain Burn and takes half Fire damage.' WHERE Item_ID='ENV-015';
UPDATE consumable_items SET Pattern='Circle 2' WHERE Item_ID='ENV-015';
UPDATE consumable_items SET Terrain_Side_Effect='Built 2026-10-27: no terrain swap. Removes Burning and Oily tile effects in the 5x5 area and fireproofs those tiles for 1200 CT (no ignition; units on them cannot gain new Burn and take half Fire damage). Fireproofed tiles currently block every Fire effect on the tile (Sand->Molten, Wet->Steam, ...).' WHERE Item_ID='ENV-015';
UPDATE elements_statuses SET effect='Cannot teleport, Blink or swap places. Cannot use skills or items that move itself (Blink, Phantom Exchange, Opportunist''s Step, Skyfall Lance, Dragon Dive, Reckless Charge, Phase Translocator, Exchange Device, Climbing Line on self). Portal Treads stop teleporting (normal walking, no teleport RT x2). Normal walking and being pushed or pulled still work. Dispellable. Source: Phase Lock (CON-019). Open: whether other units'' effects can relocate a Phase Locked unit (open_decisions).' WHERE id=125;
UPDATE elements_statuses SET notes='1 turn (ends at the end of the unit''s own next turn) | 2026-10-27 (user): refreshing Command Relay gives a fresh RT discount (the next non-Item action is discounted again).' WHERE id=126;
UPDATE elements_statuses SET effect='Defense x0.85. Does not stack: Corroded and Corroded Lesser share one group and only the strongest one applies. Dispellable. Source: Acid Flask (DAM-007, single-target). The cone Corrosion Sprayer (DAM-008) applies the weaker Corroded Lesser.' WHERE id=127;
UPDATE elements_statuses SET effect='Defense x0.90. Does not stack: shares one group with Corroded (x0.85, Acid Flask DAM-007) and only the strongest one applies. Dispellable. Source: Corrosion Sprayer (DAM-008, Cone 2).' WHERE id=128;
UPDATE project_rules SET rule='Bodiless zone: Circle 2 around the tapped tile, lasts 1200 CT. Each action by an enemy of the user that spends AP while that enemy stands in the zone costs +50 RT (once per action, even with several zones). Free actions (no AP) are not charged. Fear''s forced move is an action like any other (no special rule). Undo, a cancelled Interact and a refused not-built item give the +50 back. No data columns needed.' WHERE id=189;
UPDATE project_rules SET notes='RULE 2026-10-27. | AMENDED 2026-10-27 (user): 30 -> 50 RT; only AP-spending actions; refunds on Undo/cancel/refusal.' WHERE id=189;
UPDATE project_rules SET rule='Element wards (2026-10-26): different reductions of the same element ADD UP and the total is capped at 100%. Examples: Elemental Ward status (SUP-016, 25%), Elemental Ward Totem aura (DEP-013, 20%) and the Firebreak Projector zone (ENV-015, 50% Fire) are different effects, so they total (e.g. 25% + 20% = 45%; all three on Fire = 95%; never above 100%). Several copies of the same effect (e.g. several totems on one element) do not stack; the strongest applies. Ward status and totem apply to direct hits INCLUDING timed item hits (Thermite, Tesla Pylon, Meteor Marker, Sentry Turret and other device/pulse shots), not DoT or tile damage; Firebreak covers all Fire damage as defined in its own rule.' WHERE id=175;
UPDATE project_rules SET notes='Locked 2026-10-26 - DEP-013 build (Designer). | AMENDED 2026-10-26 (user): timed item hits included. | AMENDED 2026-10-27 (user): Firebreak 50% added; same-element reductions add up, capped at 100%.' WHERE id=175;
UPDATE terrain_effects SET col_8='None (non-elemental)' WHERE rowid=47;
UPDATE terrain_effects SET col_9='RESOLVED 2026-09-29: explosion tag intrinsic effects = tile-lowering + terrain-chain trigger only. HP damage is PER-SOURCE (barrel bomb / specific terrain-chain supplies it). Chain-depth cap retained. | 2026-10-27 (user): explosions are NON-ELEMENTAL - not Fire damage (Fire wards/Firebreak do not reduce them).' WHERE rowid=47;
UPDATE terrain_effects SET col_8='None (non-elemental)' WHERE rowid=48;
UPDATE terrain_effects SET col_9='RESOLVED 2026-09-29: pattern/tile-lowering + terrain-chain trigger are the intrinsic explosion effects. REVISED 2026-10-03: the -1 elevation drop is a property of the EXPLOSION TAG (not of Bomb Barrel/Land Mine, which had their per-object elevation wording removed). Specific terrain collapse magnitudes (Cracked Ground -3) supersede the generic -1 and do not stack. | 2026-10-27 (user): explosions are NON-ELEMENTAL - not Fire damage (Fire wards/Firebreak do not reduce them).' WHERE rowid=48;
UPDATE terrain_effects SET col_8='None (non-elemental)' WHERE rowid=50;
UPDATE terrain_effects SET col_9='RESOLVED 2026-09-29: reduction factor applies to the chained source''s own per-source damage, not to a blanket value. Consumed source cannot retrigger (TRG-011). Chain-depth cap retained. | 2026-10-27 (user): explosions are NON-ELEMENTAL - not Fire damage (Fire wards/Firebreak do not reduce them).' WHERE rowid=50;
UPDATE terrain_effects SET col_8='None (non-elemental)' WHERE rowid=51;
UPDATE terrain_effects SET col_9='Bounded & deterministic. Chain-depth cap (4) retained per 2026-09-29 ruling. | 2026-10-27 (user): explosions are NON-ELEMENTAL - not Fire damage (Fire wards/Firebreak do not reduce them).' WHERE rowid=51;
UPDATE terrain_effects SET col_8='None (non-elemental)' WHERE rowid=65;
UPDATE terrain_effects SET col_9='CORRECTED 2026-09-29 (human ruling 1): 30% -> 25% Max HP; boss-specific clause REMOVED (boss resistance applied downstream by damage pipeline, not the payload). Pattern is 3x3 (Chebyshev/box, 9 tiles) per objects_encounters and ruling 3 — WIDER than the generic explosion tag default (diamond r1, 5 tiles). Map-object bombs use their own 3x3 pattern (authored on the object), overriding the generic diamond. Tile-lowering (-1 elevation) still uses the generic explosion mechanic. | 2026-10-27 (user): explosions are NON-ELEMENTAL - not Fire damage (Fire wards/Firebreak do not reduce them).' WHERE rowid=65;
UPDATE terrain_effects SET col_3='Bomb Barrel (objects_encounters map object) explodes and supplies its own HP damage. Damage = round(25% of target Max HP) non-elemental damage, HP%-based (consistent with all CTRBLXAI HP%-scaling hazards; objects_encounters value updated to ''3x3 Explosion (25% Max HP)''). Flat-per-tile: every unit in the AOE takes the same 25% Max HP (NOT reduced by distance within the pattern). Environmental/hazard damage: does NOT use Combat Fortune. NO boss special-case in the payload — the payload is a flat 25% Max HP for ALL targets; bosses already have an authored resistance to Max-HP-based damage (core_stats Boss HP%-based rule), so boss scaling is applied DOWNSTREAM by the existing damage pipeline, not by this payload. No STR/weapon/attacker scaling — a map object has no owner stats; ownerId is the detonator for kill-credit only.' WHERE rowid=65;
UPDATE terrain_effects SET col_8='None (non-elemental)' WHERE rowid=66;
UPDATE terrain_effects SET col_9='CORRECTED 2026-09-29 (human ruling 1): 30% -> 25% Max HP; boss-specific clause REMOVED (boss resistance applied downstream). Matches updated objects_encounters value. Chain reactions allowed (a mine in another explosion''s AOE queues as a secondary source, TRG-011). | 2026-10-27 (user): explosions are NON-ELEMENTAL - not Fire damage (Fire wards/Firebreak do not reduce them).' WHERE rowid=66;
UPDATE terrain_effects SET col_3='Land Mine (objects_encounters) uses the SAME payload shape: round(25% Max HP) non-elemental damage, 3x3 box pattern, -1 elevation, environmental (no Combat Fortune). NO boss special-case in the payload — flat 25% Max HP for all targets; boss resistance is applied downstream by the existing damage pipeline. Included so both existing explosive map objects are covered by one authored standard.' WHERE rowid=66;
UPDATE terrain_effects SET col_9='Resolves SPEC 1(c). Consumed source cannot retrigger (TRG-011). Reduction multiplies the chained source''s OWN per-source damage — there is NO blanket value. Terrain-chain collapse damage (fall damage) is excluded — it is governed by movement_targeting id=14, not the explosion payload/chain rules (2026-09-29 ruling 2). | 2026-10-27 (user): explosions are NON-ELEMENTAL - not Fire damage (Fire wards/Firebreak do not reduce them).' WHERE rowid=69;
INSERT INTO project_rules VALUES (191,'Consumables','ENV-015 Firebreak Projector','Circle 2 (5x5) around the tapped tile, Range 3, Ground. Clears Burning and Oily and fireproofs the tiles for 1200 CT. The zone protects EVERY unit standing on a fireproofed tile (both sides): cannot gain new Burn, and takes half Fire damage. ''Fire damage'' = Fire hits, Burn ticks, burning-tile ticks, Molten lava end-of-turn damage, Fire weather strikes (Meteor Storm, Volcanic Eruptions) and timed Fire items. Explosions are non-elemental and are NOT Fire damage. Units already burning when they enter keep their Burn (only new Burn is blocked; their ticks are halved). Fireproofed tiles currently block every Fire effect on the tile (Sand->Molten, Wet->Steam, ...) - narrowing is an open question.','RULE 2026-10-27 (user).');
INSERT INTO open_decisions VALUES ('CON-019 Phase Locked - can OTHER units'' effects relocate a Phase Locked unit? (2026-10-27)','OPEN - user question (2026-10-27)','Phase Locked blocks the unit''s own teleport/Blink/swap and self-moving skills/items; normal walking and push/pull still work. Undecided: whether an ally''s or enemy''s swap/teleport effect (e.g. Exchange Device used by someone else) can move a Phase Locked unit.',NULL,NULL,NULL,NULL);
INSERT INTO open_decisions VALUES ('ENV-015 Firebreak - should fireproofed tiles block every Fire effect on the tile? (2026-10-27)','OPEN - user question (2026-10-27)','Currently a fireproofed tile blocks every Fire effect on the tile (Sand->Molten, Wet->Steam, ignition, ...). Undecided: keep this, or narrow it to only stopping ignition/burning.',NULL,NULL,NULL,NULL);
COMMIT;